import React, { useEffect, useState } from "react";
import { apiDelete, apiGet } from "../utils/api";
import InvoiceTable from "./InvoiceTable";
import InvoiceFilter from "./InvoiceFilter";
import Pagination from "../components/Pagination";
import { Link } from "react-router-dom";

const InvoiceIndex = () => {
    const [invoices, setInvoices] = useState([]);
    const [filter, setFilter] = useState({ limit: 10, page: 0 });
    const [persons, setPersons] = useState([]); // Použití jednoho seznamu pro kupující i prodávající
    const [totalCount, setTotalCount] = useState(0);

    const fetchInvoices = async () => {
        const query = new URLSearchParams(filter).toString();
        const [data, countData] = await Promise.all([
            apiGet(`/api/invoices?${query}`),
            apiGet(`/api/invoices/count?${query}`)
        ]);
        setInvoices(data);
        setTotalCount(countData.count);
    };

    useEffect(() => {
        fetchInvoices();
        apiGet("/api/persons").then(setPersons);
    }, [filter]);

    const deleteInvoice = async (id) => {
        try {
            await apiDelete(`/api/invoices/${id}`);
            setInvoices(invoices.filter((item) => item._id !== id));
        } catch (error) {
            console.error(error.message);
            alert(error.message);
        }
    };

    return (
        <div>
            <h1>Seznam faktur</h1>
            <InvoiceFilter filter={filter} handleChange={(e) => setFilter({ ...filter, [e.target.name]: e.target.value })} 
                confirm="Filtrovat" buyerList={persons} sellerList={persons} />
            <InvoiceTable deleteInvoice={deleteInvoice} items={invoices} />
            <Pagination filter={filter} setFilter={setFilter} totalCount={totalCount} />
            <Link to={"/invoices/create"} className="btn btn-success invoice-button">
                Nová faktura
            </Link>
        </div>
    );
};

export default InvoiceIndex;
